import json

with open('/home/ubuntu/.claude-account-1/projects/-home-ubuntu--agent-ml-research-idea-gen-0513-6-projects-faith-evidence-ie/ae70e247-4aa0-4fcb-915f-8c29a5a47125/tool-results/mcp-agent-ml-research-read_registry-1778925409761.txt', 'r') as f:
    raw = json.load(f)

registry = json.loads(raw['result'])
experiments = registry['data']['experiments']

search_terms = [
    'grpo_ced_g4_bf16',
    'grpo_ced_g8_bf16',
    'dpo_output',
    'dpo_output_1ep',
    'eval_plan_012_dpo',
    'dpo_data',
]

def search_obj(obj, terms):
    matches = set()
    if isinstance(obj, str):
        for t in terms:
            if t in obj:
                matches.add(t)
    elif isinstance(obj, dict):
        for v in obj.values():
            matches.update(search_obj(v, terms))
    elif isinstance(obj, list):
        for item in obj:
            matches.update(search_obj(item, terms))
    return matches

results = []
for exp_name, exp_data in experiments.items():
    matched_terms = search_obj(exp_data, search_terms)
    if matched_terms:
        results.append((exp_name, exp_data, matched_terms))

print(f'Total experiments in registry: {len(experiments)}')
print(f'Matching experiments: {len(results)}')
print()

for exp_name, exp_data, terms in results:
    print(f'{'='*70}')
    print(f'EXPERIMENT: {exp_name}')
    print(f'Matched terms: {sorted(terms)}')
    print(f'Status: {exp_data.get(\"status\", \"N/A\")}')
    print(f'Conclusion: {exp_data.get(\"conclusion\", \"N/A\")}')

    # Metrics
    metrics = exp_data.get('metrics', exp_data.get('result', {}).get('metrics', None))
    if metrics:
        print(f'Metrics: {json.dumps(metrics, ensure_ascii=False)}')
    else:
        # check inside result
        result = exp_data.get('result', {})
        if isinstance(result, dict) and result:
            print(f'Result: {json.dumps(result, ensure_ascii=False)[:500]}')

    # Key directories referenced
    spec = exp_data.get('spec', {})
    dirs_of_interest = []
    for field in ['output_dir', 'checkpoint_path', 'command', 'data_path', 'log_path']:
        val = spec.get(field, '')
        if val:
            for t in terms:
                if t in str(val):
                    dirs_of_interest.append(f'  {field}: {val}')
                    break
    if dirs_of_interest:
        print('Referenced directories:')
        for d in dirs_of_interest:
            print(d)

    # Notes
    notes = exp_data.get('notes', spec.get('notes', spec.get('hypothesis', '')))
    if notes:
        print(f'Notes/Hypothesis: {notes}')

    print()
